const DDL_STATEMENTS = [
  "CREATE TABLE IF NOT EXISTS User (\n    id TEXT PRIMARY KEY,\n    email TEXT UNIQUE NOT NULL,\n    name TEXT NOT NULL,\n    role TEXT NOT NULL DEFAULT 'SERVICE_STAFF',\n    password TEXT NOT NULL DEFAULT 'havenso123',\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS \"Table\" (\n    id TEXT PRIMARY KEY,\n    tableNumber TEXT UNIQUE NOT NULL,\n    capacity INTEGER NOT NULL DEFAULT 4,\n    location TEXT NOT NULL DEFAULT 'Indoor',\n    status TEXT NOT NULL DEFAULT 'AVAILABLE',\n    qrCode TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS CustomerSession (\n    id TEXT PRIMARY KEY,\n    tableId TEXT,\n    tableNumber TEXT,\n    status TEXT NOT NULL DEFAULT 'ACTIVE',\n    expiresAt DATETIME,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS Category (\n    id TEXT PRIMARY KEY,\n    name TEXT NOT NULL,\n    slug TEXT UNIQUE NOT NULL,\n    displayOrder INTEGER NOT NULL DEFAULT 0,\n    isActive BOOLEAN NOT NULL DEFAULT 1,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS MenuItem (\n    id TEXT PRIMARY KEY,\n    categoryId TEXT NOT NULL,\n    name TEXT NOT NULL,\n    slug TEXT UNIQUE NOT NULL,\n    description TEXT NOT NULL,\n    price REAL NOT NULL,\n    imageUrl TEXT NOT NULL,\n    isAvailable BOOLEAN NOT NULL DEFAULT 1,\n    stock INTEGER NOT NULL DEFAULT 50,\n    preparationTime INTEGER NOT NULL DEFAULT 5,\n    ingredients TEXT,\n    allergens TEXT,\n    recommendationTags TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (categoryId) REFERENCES Category(id) ON DELETE CASCADE\n  )",
  "CREATE TABLE IF NOT EXISTS InventoryItem (\n    id TEXT PRIMARY KEY,\n    name TEXT UNIQUE NOT NULL,\n    stock REAL NOT NULL DEFAULT 0,\n    unit TEXT NOT NULL DEFAULT 'pcs',\n    minStock REAL NOT NULL DEFAULT 10,\n    status TEXT NOT NULL DEFAULT 'AVAILABLE',\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS Cart (\n    id TEXT PRIMARY KEY,\n    sessionId TEXT UNIQUE NOT NULL,\n    status TEXT NOT NULL DEFAULT 'ACTIVE',\n    subtotal REAL NOT NULL DEFAULT 0,\n    tax REAL NOT NULL DEFAULT 0,\n    discount REAL NOT NULL DEFAULT 0,\n    total REAL NOT NULL DEFAULT 0,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS CartItem (\n    id TEXT PRIMARY KEY,\n    cartId TEXT NOT NULL,\n    menuItemId TEXT NOT NULL,\n    quantity INTEGER NOT NULL DEFAULT 1,\n    customizations TEXT,\n    unitPrice REAL NOT NULL,\n    subtotal REAL NOT NULL,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (cartId) REFERENCES Cart(id) ON DELETE CASCADE\n  )",
  "CREATE TABLE IF NOT EXISTS \"Order\" (\n    id TEXT PRIMARY KEY,\n    orderNumber TEXT UNIQUE NOT NULL,\n    sessionId TEXT NOT NULL,\n    tableId TEXT,\n    tableNumber TEXT,\n    status TEXT NOT NULL DEFAULT 'QUEUED',\n    paymentStatus TEXT NOT NULL DEFAULT 'PENDING',\n    subtotal REAL NOT NULL DEFAULT 0,\n    tax REAL NOT NULL DEFAULT 0,\n    discount REAL NOT NULL DEFAULT 0,\n    total REAL NOT NULL DEFAULT 0,\n    notes TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS OrderItem (\n    id TEXT PRIMARY KEY,\n    orderId TEXT NOT NULL,\n    menuItemId TEXT NOT NULL,\n    nameSnapshot TEXT NOT NULL,\n    priceSnapshot REAL NOT NULL,\n    quantity INTEGER NOT NULL DEFAULT 1,\n    customizations TEXT,\n    subtotal REAL NOT NULL,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (orderId) REFERENCES \"Order\"(id) ON DELETE CASCADE\n  )",
  "CREATE TABLE IF NOT EXISTS Payment (\n    id TEXT PRIMARY KEY,\n    orderId TEXT NOT NULL,\n    provider TEXT NOT NULL DEFAULT 'QRIS',\n    providerReference TEXT,\n    amount REAL NOT NULL,\n    currency TEXT NOT NULL DEFAULT 'IDR',\n    status TEXT NOT NULL DEFAULT 'PENDING',\n    metadata TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (orderId) REFERENCES \"Order\"(id) ON DELETE CASCADE\n  )",
  "CREATE TABLE IF NOT EXISTS Conversation (\n    id TEXT PRIMARY KEY,\n    sessionId TEXT UNIQUE NOT NULL,\n    status TEXT NOT NULL DEFAULT 'ACTIVE',\n    aiStatus TEXT NOT NULL DEFAULT 'ACTIVE',\n    communicationProfile TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS Message (\n    id TEXT PRIMARY KEY,\n    conversationId TEXT NOT NULL,\n    senderType TEXT NOT NULL,\n    content TEXT NOT NULL,\n    metadata TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (conversationId) REFERENCES Conversation(id) ON DELETE CASCADE\n  )",
  "CREATE TABLE IF NOT EXISTS SupportTicket (\n    id TEXT PRIMARY KEY,\n    conversationId TEXT,\n    orderId TEXT,\n    tableId TEXT,\n    tableNumber TEXT,\n    type TEXT NOT NULL DEFAULT 'PHYSICAL_ASSISTANCE',\n    priority TEXT NOT NULL DEFAULT 'P1',\n    status TEXT NOT NULL DEFAULT 'WAITING',\n    summary TEXT NOT NULL,\n    metadata TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,\n    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )",
  "CREATE TABLE IF NOT EXISTS AuditLog (\n    id TEXT PRIMARY KEY,\n    actionType TEXT NOT NULL,\n    performedBy TEXT NOT NULL,\n    entityType TEXT NOT NULL,\n    entityId TEXT,\n    details TEXT,\n    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP\n  )"
];

